export const TOTAL_CHARACTER_MODELS = CHARACTER_MODELS.length;

export function normalizeSkinId(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  const idx = Math.trunc(n);
  return ((idx % TOTAL_CHARACTER_MODELS) + TOTAL_CHARACTER_MODELS) % TOTAL_CHARACTER_MODELS;
}

export function getCharacterModel(skinId) {
  return CHARACTER_MODELS[normalizeSkinId(skinId)] || CHARACTER_MODELS[0];
}
